MOTIF_NAME = 'peripheral influence and weak group edge'
MOTIF_DESCRIPTION = 'The evaluated side has a clear corner and side influence surplus, helped by greater pressure on opposing weak groups.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    s = ''.join(board_rows)
    score = 3.2 if color == 'W' else -3.2

    offs = []
    for dr in range(-4, 5):
        for dc in range(-4, 5):
            d = abs(dr) + abs(dc)
            if 0 < d <= 4:
                offs.append((dr, dc, 5 - d))

    for r in range(19):
        base = r * 19
        for c in range(19):
            edge = min(r, c, 18 - r, 18 - c)
            if edge > 4:
                continue
            p = base + c
            ch = s[p]
            corner = (r < 6 or r > 12) and (c < 6 or c > 12)
            wt = 1.25 if corner else (1.0 if edge <= 2 else 0.65)
            if ch == color:
                score += 0.45 * wt
            elif ch == opp:
                score -= 0.45 * wt
            else:
                oi = 0
                ei = 0
                for dr, dc, w in offs:
                    nr = r + dr
                    nc = c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        v = s[nr * 19 + nc]
                        if v == color:
                            oi += w
                        elif v == opp:
                            ei += w
                diff = oi - ei
                if diff > 2:
                    score += wt * (0.52 + min(0.48, diff * 0.035))
                elif diff < -2:
                    score -= wt * (0.52 + min(0.48, -diff * 0.035))

    seen = [False] * 361
    libmark = [0] * 361
    mark = 0
    for i, ch in enumerate(s):
        if ch == '.' or seen[i]:
            continue
        mark += 1
        q = [i]
        seen[i] = True
        h = 0
        size = 0
        contacts = 0
        libs = []
        while h < len(q):
            p = q[h]
            h += 1
            size += 1
            if p >= 19:
                np = p - 19
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1
            if p < 342:
                np = p + 19
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1
            if p % 19:
                np = p - 1
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1
            if p % 19 != 18:
                np = p + 1
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1

        badc = opp if ch == color else color
        eyeish = 0
        for p in libs:
            bad = False
            if p >= 19 and s[p - 19] == badc:
                bad = True
            if p < 342 and s[p + 19] == badc:
                bad = True
            if p % 19 and s[p - 1] == badc:
                bad = True
            if p % 19 != 18 and s[p + 1] == badc:
                bad = True
            if not bad:
                eyeish += 1

        lc = len(libs)
        strain = 0.0
        if lc <= 1:
            strain = min(16.0, 4.0 + 1.6 * size)
        elif lc == 2:
            strain = 2.0 + min(8.0, 0.55 * size)
            if eyeish:
                strain *= 0.35
        elif lc == 3 and eyeish == 0 and contacts >= 4:
            strain = 1.4 + min(3.0, 0.22 * size)
        elif lc <= 5 and size >= 7 and eyeish == 0 and contacts > lc:
            strain = 1.2

        if ch == color:
            score -= 0.75 * strain
        else:
            score += 0.75 * strain

    return score > 3.8

MOTIF_NAME = 'net low-liberty attack swing'
MOTIF_DESCRIPTION = 'The evaluated side has a larger low-liberty capture threat against opposing groups than it must defend.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    s = ''.join(board_rows)
    seen = [False] * 361
    libmark = [0] * 361
    mark = 0
    attack = 0.0
    defend = 0.0
    max_a = 0.0
    max_d = 0.0
    at_a = 0
    at_d = 0

    for i, ch in enumerate(s):
        if ch == '.' or seen[i]:
            continue
        mark += 1
        q = [i]
        seen[i] = True
        h = 0
        size = 0
        contacts = 0
        libs = []
        while h < len(q):
            p = q[h]
            h += 1
            size += 1
            if p >= 19:
                np = p - 19
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1
            if p < 342:
                np = p + 19
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1
            if p % 19:
                np = p - 1
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1
            if p % 19 != 18:
                np = p + 1
                v = s[np]
                if v == '.':
                    if libmark[np] != mark:
                        libmark[np] = mark
                        libs.append(np)
                elif v == ch:
                    if not seen[np]:
                        seen[np] = True
                        q.append(np)
                else:
                    contacts += 1

        eyeish = 0
        tight = 0
        for p in libs:
            bad = 0
            friend = 0
            if p >= 19:
                v = s[p - 19]
                if v == ch:
                    friend += 1
                elif v != '.':
                    bad += 1
            if p < 342:
                v = s[p + 19]
                if v == ch:
                    friend += 1
                elif v != '.':
                    bad += 1
            if p % 19:
                v = s[p - 1]
                if v == ch:
                    friend += 1
                elif v != '.':
                    bad += 1
            if p % 19 != 18:
                v = s[p + 1]
                if v == ch:
                    friend += 1
                elif v != '.':
                    bad += 1
            if bad == 0:
                eyeish += 1
            elif bad >= friend:
                tight += 1
            else:
                tight += 0.5

        lc = len(libs)
        val = 0.0
        if lc <= 1:
            val = 5.0 + 2.2 * size + 0.3 * contacts
        elif lc == 2:
            val = 3.0 + 1.15 * size + 0.2 * contacts + 0.9 * tight
            if eyeish >= 2:
                val *= 0.12
            elif eyeish == 1:
                val *= 0.48
        elif lc == 3:
            if eyeish == 0:
                val = 1.5 + 0.65 * size + 0.22 * contacts + 0.65 * tight
            elif eyeish == 1 and tight >= 2 and contacts >= 4 and size <= 6:
                val = 1.1 + 0.35 * size
        elif lc == 4:
            if eyeish == 0 and tight >= 2 and contacts >= 5:
                val = 0.8 + 0.42 * size + 0.18 * contacts + 0.35 * tight
        elif lc <= 6 and size >= 7 and eyeish == 0 and tight >= lc - 1 and contacts >= lc + 3:
            val = 0.3 * size + 0.18 * contacts + 0.35 * tight

        if val > 32.0:
            val = 32.0

        if ch == color:
            defend += val
            if val > max_d:
                max_d = val
            if lc == 1:
                at_d += size
        elif ch == opp:
            attack += val
            if val > max_a:
                max_a = val
            if lc == 1:
                at_a += size

    net = attack - defend
    return (attack >= 8.5 and net >= 4.5 and max_a >= max_d + 1.0) or (at_a >= 3 and at_d == 0 and attack >= 5.0) or (attack >= 16.0 and net >= 8.0)

MOTIF_NAME = 'fast positive ownership estimate'
MOTIF_DESCRIPTION = 'The evaluated side has a positive fast area estimate using stones, komi, territory, influence, and weak-group pressure.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    N = 361
    s = ''.join(board_rows)
    score = 7.5 if color == 'W' else -7.5
    own = []
    enemy = []

    for i, ch in enumerate(s):
        if ch == color:
            score += 1.0
            own.append(i)
        elif ch == opp:
            score -= 1.0
            enemy.append(i)

    def dist(src):
        d = [99] * N
        q = src[:]
        for p in q:
            d[p] = 0
        h = 0
        while h < len(q):
            p = q[h]
            h += 1
            nd = d[p] + 1
            if p >= 19:
                np = p - 19
                if d[np] > nd:
                    d[np] = nd
                    q.append(np)
            if p < 342:
                np = p + 19
                if d[np] > nd:
                    d[np] = nd
                    q.append(np)
            if p % 19:
                np = p - 1
                if d[np] > nd:
                    d[np] = nd
                    q.append(np)
            if p % 19 != 18:
                np = p + 1
                if d[np] > nd:
                    d[np] = nd
                    q.append(np)
        return d

    od = dist(own)
    ed = dist(enemy)

    seen = [False] * N
    for i, ch in enumerate(s):
        if ch == '.' and not seen[i]:
            q = [i]
            seen[i] = True
            h = 0
            oa = 0
            ea = 0
            while h < len(q):
                p = q[h]
                h += 1
                if p >= 19:
                    np = p - 19
                    v = s[np]
                    if v == '.':
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    elif v == color:
                        oa += 1
                    elif v == opp:
                        ea += 1
                if p < 342:
                    np = p + 19
                    v = s[np]
                    if v == '.':
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    elif v == color:
                        oa += 1
                    elif v == opp:
                        ea += 1
                if p % 19:
                    np = p - 1
                    v = s[np]
                    if v == '.':
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    elif v == color:
                        oa += 1
                    elif v == opp:
                        ea += 1
                if p % 19 != 18:
                    np = p + 1
                    v = s[np]
                    if v == '.':
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    elif v == color:
                        oa += 1
                    elif v == opp:
                        ea += 1
            ln = len(q)
            if oa and not ea:
                score += ln
            elif ea and not oa:
                score -= ln
            else:
                if ln <= 60:
                    if oa >= ea * 3 + 4:
                        score += 0.55 * ln
                        continue
                    if ea >= oa * 3 + 4:
                        score -= 0.55 * ln
                        continue
                for p in q:
                    a = od[p]
                    b = ed[p]
                    if a < b:
                        score += 0.8 if a + 1 < b else 0.3
                    elif b < a:
                        score -= 0.8 if b + 1 < a else 0.3

    seen = [False] * N
    libmark = [0] * N
    mark = 0
    for i, ch in enumerate(s):
        if ch != '.' and not seen[i]:
            mark += 1
            q = [i]
            seen[i] = True
            h = 0
            size = 0
            libs = []
            contacts = 0
            while h < len(q):
                p = q[h]
                h += 1
                size += 1
                if p >= 19:
                    np = p - 19
                    v = s[np]
                    if v == '.':
                        if libmark[np] != mark:
                            libmark[np] = mark
                            libs.append(np)
                    elif v == ch:
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    else:
                        contacts += 1
                if p < 342:
                    np = p + 19
                    v = s[np]
                    if v == '.':
                        if libmark[np] != mark:
                            libmark[np] = mark
                            libs.append(np)
                    elif v == ch:
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    else:
                        contacts += 1
                if p % 19:
                    np = p - 1
                    v = s[np]
                    if v == '.':
                        if libmark[np] != mark:
                            libmark[np] = mark
                            libs.append(np)
                    elif v == ch:
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    else:
                        contacts += 1
                if p % 19 != 18:
                    np = p + 1
                    v = s[np]
                    if v == '.':
                        if libmark[np] != mark:
                            libmark[np] = mark
                            libs.append(np)
                    elif v == ch:
                        if not seen[np]:
                            seen[np] = True
                            q.append(np)
                    else:
                        contacts += 1
            lc = len(libs)
            eyeish = 0
            badc = opp if ch == color else color
            for p in libs:
                bad = False
                if p >= 19 and s[p - 19] == badc:
                    bad = True
                if p < 342 and s[p + 19] == badc:
                    bad = True
                if p % 19 and s[p - 1] == badc:
                    bad = True
                if p % 19 != 18 and s[p + 1] == badc:
                    bad = True
                if not bad:
                    eyeish += 1
            val = 0.0
            if lc <= 1:
                val = min(22.0, 4.0 + 2.0 * size)
            elif lc == 2 and eyeish < 2:
                val = min(12.0, 1.0 + 0.8 * size)
                if eyeish == 1:
                    val *= 0.5
            elif lc == 3 and eyeish == 0 and size <= 4 and contacts >= 5:
                val = 2.0
            if ch == color:
                score -= val
            else:
                score += val

    return score > 0.0

MOTIF_NAME = 'resolved eye-space prisoner swing'
MOTIF_DESCRIPTION = 'The evaluated side has more small secured eye spaces and enclosed opposing prisoner stones than the opponent.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    s = ''.join(board_rows)

    nb = [[] for _ in range(361)]
    for p in range(361):
        if p >= 19:
            nb[p].append(p - 19)
        if p < 342:
            nb[p].append(p + 19)
        if p % 19:
            nb[p].append(p - 1)
        if p % 19 != 18:
            nb[p].append(p + 1)

    gid = [-1] * 361
    gcol = []
    gsize = []
    glibs = []
    gcont = []
    libmark = [0] * 361
    mark = 0

    for i, ch in enumerate(s):
        if ch == '.' or gid[i] >= 0:
            continue
        g = len(gcol)
        q = [i]
        gid[i] = g
        h = 0
        libs = []
        cont = 0
        mark += 1
        while h < len(q):
            p = q[h]
            h += 1
            for y in nb[p]:
                v = s[y]
                if v == '.':
                    if libmark[y] != mark:
                        libmark[y] = mark
                        libs.append(y)
                elif v == ch:
                    if gid[y] < 0:
                        gid[y] = g
                        q.append(y)
                else:
                    cont += 1
        gcol.append(ch)
        gsize.append(len(q))
        glibs.append(libs)
        gcont.append(cont)

    n = len(gcol)
    geyes = [0] * n
    gfake = [0] * n
    sf = [1.0] * n
    stones_o = stones_e = 0
    weak_o = weak_e = 0.0
    sev_o = sev_e = 0

    for g, ch in enumerate(gcol):
        enemy = 'W' if ch == 'B' else 'B'
        eyes = fake = 0
        for p in glibs[g]:
            bad = False
            for y in nb[p]:
                if s[y] == enemy:
                    bad = True
                    break
            if bad:
                continue
            r = p // 19
            c = p - r * 19
            diag = off = 0
            if r and c:
                diag += 1 if s[p - 20] == enemy else 0
            else:
                off += 1
            if r and c < 18:
                diag += 1 if s[p - 18] == enemy else 0
            else:
                off += 1
            if r < 18 and c:
                diag += 1 if s[p + 18] == enemy else 0
            else:
                off += 1
            if r < 18 and c < 18:
                diag += 1 if s[p + 20] == enemy else 0
            else:
                off += 1
            if diag <= (1 if off else 0):
                eyes += 1
            elif diag >= 2:
                fake += 1
        geyes[g] = eyes
        gfake[g] = fake

        sz = gsize[g]
        lc = len(glibs[g])
        cont = gcont[g]
        if eyes >= 2 or lc >= 11:
            f = 1.22
        elif eyes and lc >= 6:
            f = 1.08
        elif lc >= 7:
            f = 0.98
        elif lc >= 5:
            f = 0.82
        elif lc == 4:
            f = 0.70 if eyes else 0.56
        elif lc == 3:
            f = 0.58 if eyes else 0.38
        elif lc == 2:
            f = 0.43 if eyes else 0.20
        else:
            f = 0.08
        sf[g] = f

        sev = 0
        weak = 0.0
        if lc <= 1:
            weak = 4.0 + 1.05 * sz + 0.08 * cont
            sev = 1
        elif lc == 2:
            weak = 1.25 + 0.40 * sz + 0.06 * cont
            if eyes:
                weak *= 0.42
            else:
                sev = 1
        elif lc == 3 and eyes == 0:
            weak = 0.55 + 0.14 * sz + 0.05 * cont
        elif lc <= 5 and eyes == 0 and cont >= lc + 3:
            weak = 0.20 + 0.06 * sz + 0.04 * cont

        if ch == color:
            stones_o += sz
            weak_o += weak
            sev_o += sev
        else:
            stones_e += sz
            weak_e += weak
            sev_e += sev

    rid = [-1] * 361
    rowner = []
    rsize = []
    terr_b = terr_w = 0.0
    micro_b = micro_w = 0

    for i, ch in enumerate(s):
        if ch != '.' or rid[i] >= 0:
            continue
        k = len(rowner)
        q = [i]
        rid[i] = k
        h = 0
        tb = tw = 0
        sb = sw = 0.0
        edge = False
        while h < len(q):
            p = q[h]
            h += 1
            r = p // 19
            c = p - r * 19
            if r == 0 or r == 18 or c == 0 or c == 18:
                edge = True
            for y in nb[p]:
                v = s[y]
                if v == '.':
                    if rid[y] < 0:
                        rid[y] = k
                        q.append(y)
                elif v == 'B':
                    tb += 1
                    sb += sf[gid[y]]
                else:
                    tw += 1
                    sw += sf[gid[y]]
        sz = len(q)
        owner = '.'
        exact = False
        if tb and not tw:
            owner = 'B'
            exact = True
        elif tw and not tb:
            owner = 'W'
            exact = True
        elif sz <= 14:
            if sb > sw * 1.75 + 1.1 and sb - sw >= 1.7 + 0.05 * sz:
                owner = 'B'
            elif sw > sb * 1.75 + 1.1 and sw - sb >= 1.7 + 0.05 * sz:
                owner = 'W'
        rowner.append(owner)
        rsize.append(sz)

        if owner != '.':
            touch = tb if owner == 'B' else tw
            val = 0.0
            if sz <= 2:
                val = sz + 1.15
            elif sz <= 7:
                val = sz + 0.65
            elif sz <= 14:
                val = 0.78 * sz
            elif exact and sz <= 24:
                val = 0.38 * sz
            if val and touch >= 2:
                if edge:
                    val *= 1.08
                if owner == 'B':
                    terr_b += val
                    if sz <= 10:
                        micro_b += 1
                else:
                    terr_w += val
                    if sz <= 10:
                        micro_w += 1

    dead_b = dead_w = 0.0
    trap_b = trap_w = 0
    false_b = false_w = 0.0

    for g, ch in enumerate(gcol):
        lc = len(glibs[g])
        eyes = geyes[g]
        sz = gsize[g]
        if eyes >= 2 or lc >= 9 or sz > 26:
            continue
        enemy = 'W' if ch == 'B' else 'B'
        elib = slib = 0
        espace = sspace = 0
        for p in glibs[g]:
            k = rid[p]
            if k >= 0:
                ow = rowner[k]
                if ow == enemy:
                    elib += 1
                    rs = rsize[k]
                    espace += 10 if rs > 10 else rs
                elif ow == ch:
                    slib += 1
                    rs = rsize[k]
                    sspace += 10 if rs > 10 else rs

        cont = gcont[g]
        caught = False
        if lc <= 2 and eyes == 0:
            caught = True
        elif lc <= 4 and eyes == 0 and (elib >= lc - 1 or cont >= 2 * lc + min(sz, 7)):
            caught = True
        elif lc <= 6 and eyes == 0 and elib * 2 >= lc and cont >= lc + 2:
            caught = True
        elif eyes == 1 and lc <= 5 and elib >= lc - 1 and cont >= lc:
            caught = True
        elif gfake[g] and eyes == 0 and lc <= 7 and elib + 1 >= slib + lc // 2 and cont >= lc + 1:
            caught = True

        if not caught:
            continue

        val = 0.85 + 0.62 * min(sz, 16) + 0.34 * max(0, 7 - lc)
        val += 0.23 * elib + 0.035 * min(cont, 26) + 0.20 * min(espace, 12)
        if gfake[g]:
            val += 0.45 * min(gfake[g], 3)
        if eyes:
            val *= 0.55
        if slib:
            val *= 0.64 if slib == 1 else 0.42
        if lc >= 6:
            val *= 0.76
        if val < 2.0:
            continue

        if enemy == 'B':
            dead_b += val
            trap_b += 1
            if gfake[g]:
                false_b += val
        else:
            dead_w += val
            trap_w += 1
            if gfake[g]:
                false_w += val

    if color == 'B':
        terr_o, terr_e = terr_b, terr_w
        dead_o, dead_e = dead_b, dead_w
        micro_o, micro_e = micro_b, micro_w
        trap_o, trap_e = trap_b, trap_w
        false_o, false_e = false_b, false_w
    else:
        terr_o, terr_e = terr_w, terr_b
        dead_o, dead_e = dead_w, dead_b
        micro_o, micro_e = micro_w, micro_b
        trap_o, trap_e = trap_w, trap_b
        false_o, false_e = false_w, false_b

    mat = stones_o - stones_e + (6.5 if color == 'W' else -6.5)
    resolved_o = dead_o + 0.55 * terr_o
    resolved_e = dead_e + 0.55 * terr_e
    score = resolved_o - resolved_e + 0.23 * (weak_e - weak_o) + 0.10 * mat
    safe = weak_o <= weak_e + 8.5 and sev_o <= sev_e + 2
    loose = weak_o <= weak_e + 11.5 and sev_o <= sev_e + 3

    return (
        safe and dead_o >= dead_e + 3.0 and resolved_o >= resolved_e + 5.0
