            sev[k] += 1
        elif lc == 2:
            weak[k] += 1.45 + 0.34 * z + 0.05 * contact[g]
            sev[k] += 1
        elif lc == 3:
            weak[k] += 0.55 + 0.11 * z + 0.035 * contact[g]
        elif lc <= 5 and contact[g] >= lc + 3:
            weak[k] += 0.20 + 0.045 * z + 0.03 * contact[g]
        if lc >= 3:
            mob[k] += min(lc, 10) * (0.75 + 0.04 * min(z, 14)) / (z ** 0.35)
        else:
            mob[k] -= 0.8 + 0.12 * z

    def vuln(g):
        lc = len(libs[g])
        z = size[g]
        v = 0.0
        if lc <= 7:
            v += (7.1 - lc) * (0.58 + 0.075 * min(z, 16))
        if lc <= 5:
            v += 0.045 * min(contact[g], 24)
        if z <= 4 and contact[g] >= 2:
            v += 0.35
        return v

    front = [0.0, 0.0]
    reserve = [0.0, 0.0]
    cuts = [0, 0]
    conns = [0, 0]
    mid = [0, 0]
    contested = 0

    for p, ch in enumerate(s):
        if ch != '.':
            continue
        r = p // 19
        c = p % 19
        gs = [[], []]
        adj = [0, 0]
        dg = [0, 0]
        for y in (p - 19 if p >= 19 else -1,
                  p + 19 if p < 342 else -1,
                  p - 1 if c else -1,
                  p + 1 if c != 18 else -1):
            if y < 0:
                continue
            v = s[y]
            if v == 'B' or v == 'W':
                k = 0 if v == 'B' else 1
                adj[k] += 1
                g = gid[y]
                if g not in gs[k]:
                    gs[k].append(g)
        for y in (p - 20 if r and c else -1,
                  p - 18 if r and c < 18 else -1,
                  p + 18 if r < 18 and c else -1,
                  p + 20 if r < 18 and c < 18 else -1):
            if y >= 0:
                v = s[y]
                if v == 'B':
                    dg[0] += 1
                elif v == 'W':
                    dg[1] += 1

        if gs[0] and gs[1]:
            contested += 1
            lb = lw = 0
            for rr in range(max(0, r - 2), min(19, r + 3)):
