                for cc in range(max(0, c - 2), min(19, c + 3)):
                    v = s[base + cc]
                    if v == 'B':
                        lb += 1
                    elif v == 'W':
                        lw += 1
            d = min(r, c, 18 - r, 18 - c)
            for k in (0, 1):
                o = 1 - k
                atk = 0.0
                dfn = 0.0
                for g in gs[o]:
                    atk += vuln(g)
                for g in gs[k]:
                    lc = len(libs[g])
                    if lc <= 6:
                        dfn += (6.2 - lc) * (0.42 + 0.055 * min(size[g], 14))
                bal = (lb - lw) if k == 0 else (lw - lb)
                v = atk - 0.64 * dfn
                v += 0.52 * (adj[k] - adj[o]) + 0.30 * (dg[k] - dg[o])
                if len(gs[o]) >= 2:
                    v += 0.95 + 0.25 * (len(gs[o]) - 2)
                if len(gs[k]) >= 2:
                    v += 0.48
                if -4 <= bal <= 6:
                    v *= 1.18
                elif bal > 6:
                    v *= 0.55
                else:
                    v *= 0.70
                if d == 0:
                    v *= 0.78
                elif d >= 4:
                    v *= 1.08
                if v > 1.15:
                    front[k] += v
                    if len(gs[o]) >= 2:
                        cuts[k] += 1
                    if len(gs[k]) >= 2:
                        conns[k] += 1
                    if d >= 2:
                        mid[k] += 1
        elif gs[0] or gs[1]:
            k = 0 if gs[0] else 1
            if contact[gs[k][0]] > 0:
                m = 0
                for g in gs[k]:
                    lc = len(libs[g])
                    if lc > m:
                        m = lc
                reserve[k] += 0.30 + 0.08 * min(m, 8) + 0.10 * dg[k]

    me = 0 if color == 'B' else 1
    op = 1 - me
    total = stones[0] + stones[1]
    mat = stones[me] - stones[op] + (6.5 if color == 'W' else -6.5)
    raw = front[me] - front[op]
    net = raw + 0.34 * (cuts[me] - cuts[op]) + 0.22 * (conns[me] - conns[op])
    net += 0.08 * (reserve[me] - reserve[op]) + 0.10 * (mob[me] - mob[op])
    net += 0.18 * (weak[op] - weak[me])
    safe = weak[me] <= weak[op] + 4.2 and sev[me] <= sev[op] + 1

    return (
        total >= 30 and contested >= 9 and safe and -18.0 <= mat <= 18.0
        and raw >= 3.8 and net >= 5.4
        and cuts[me] + conns[me] >= cuts[op] + conns[op] + 1
