            weak = 1.25 + 0.38 * sz + 0.06 * cont
            if eys:
                weak *= 0.42
            else:
                sev = 1
        elif lc == 3 and eys == 0:
            weak = 0.58 + 0.14 * sz + 0.05 * cont
        elif lc <= 5 and eys == 0 and cont >= lc + 2:
            weak = 0.20 + 0.06 * sz + 0.04 * cont

        if ch == 'B':
            stones_b += sz
            weak_b += weak
            sev_b += sev
        else:
            stones_w += sz
            weak_w += weak
            sev_w += sev

    owner = [0] * 361
    fence_b = fence_w = 0.0
    strong_b = strong_w = 0.0
    sec = [0.0] * 9
    dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))

    for p, ch in enumerate(s):
        if ch != '.':
            continue
        r = p // 19
        c = p - r * 19
        sb = sw = 0.0
        bd = wd = 0
        hit = ['.', '.', '.', '.']
        for j in range(4):
            dr, dc = dirs[j]
            rr = r + dr
            cc = c + dc
            for dist in range(1, 11):
                if rr < 0 or rr >= 19 or cc < 0 or cc >= 19:
                    break
                q = rr * 19 + cc
                v = s[q]
                if v != '.':
                    f = sf[gid[q]]
                    val = (11 - dist) * 0.18 * f
                    if v == 'B':
                        sb += val
                        if f >= 0.42:
                            hit[j] = 'B'
                            bd += 1
                    else:
                        sw += val
                        if f >= 0.42:
                            hit[j] = 'W'
                            wd += 1
                    break
                rr += dr
                cc += dc

        dedge = min(r, c, 18 - r, 18 - c)
        edge_dirs = (1 if r <= 2 else 0) + (1 if r >= 16 else 0) + (1 if c <= 2 else 0) + (1 if c >= 16 else 0)
        baxis = (1 if hit[0] == 'B' or hit[1] == 'B' else 0) + (1 if hit[2] == 'B' or hit[3] == 'B' else 0)
        waxis = (1 if hit[0] == 'W' or hit[1] == 'W' else 0) + (1 if hit[2] == 'W' or hit[3] == 'W' else 0)
        bshape = bd >= 3 or (bd >= 2 and baxis == 2) or (dedge <= 3 and bd + edge_dirs >= 3 and baxis >= 1)
        wshape = wd >= 3 or (wd >= 2 and waxis == 2) or (dedge <= 3 and wd + edge_dirs >= 3 and waxis >= 1)
        val = 1.12 if dedge <= 2 else (1.0 if dedge <= 5 else 0.84)
        k = (0 if r <= 5 else (1 if r <= 12 else 2)) * 3 + (0 if c <= 5 else (1 if c <= 12 else 2))

        if bshape and sb > sw * 1.30 + 0.55:
            owner[p] = 1
            fence_b += val
            sec[k] += val
            if bd >= 3 or sb > sw * 1.75 + 1.25:
                strong_b += val
        elif wshape and sw > sb * 1.30 + 0.55:
            owner[p] = -1
            fence_w += val
            sec[k] -= val
            if wd >= 3 or sw > sb * 1.75 + 1.25:
                strong_w += val

    trap_b = trap_w = 0.0
    for g, ch in enumerate(gcol):
        lc = len(glibs[g])
        if lc > 5 or eyes[g] >= 2 or gsize[g] > 30:
            continue
        dom = friend = 0
        for p in glibs[g]:
            o = owner[p]
            if ch == 'B':
                if o == -1:
                    dom += 1
                elif o == 1:
                    friend += 1
            else:
                if o == 1:
                    dom += 1
                elif o == -1:
                    friend += 1
        caught = False
        if lc <= 1:
            caught = True
        elif eyes[g] == 0 and lc <= 2 and dom >= 1:
            caught = True
        elif eyes[g] == 0 and lc <= 4 and dom * 2 >= lc + 1 and gcont[g] >= lc:
            caught = True
        elif lc <= 5 and dom >= lc - 1 and friend == 0 and gcont[g] >= lc + 1:
            caught = True
        if not caught:
            continue
        val = 0.8 + 0.58 * min(gsize[g], 18) + 0.35 * max(0, 6 - lc) + 0.28 * dom
        if eyes[g]:
            val *= 0.55
        if friend:
            val *= 0.72
        if ch == 'B':
            trap_w += val
        else:
            trap_b += val

    if color == 'B':
        stones_o, stones_e = stones_b, stones_w
        weak_o, weak_e = weak_b, weak_w
        sev_o, sev_e = sev_b, sev_w
        fence_o, fence_e = fence_b, fence_w
        strong_o, strong_e = strong_b, strong_w
        trap_o, trap_e = trap_b, trap_w
        sign = 1.0
    else:
        stones_o, stones_e = stones_w, stones_b
        weak_o, weak_e = weak_w, weak_b
        sev_o, sev_e = sev_w, sev_b
        fence_o, fence_e = fence_w, fence_b
        strong_o, strong_e = strong_w, strong_b
        trap_o, trap_e = trap_w, trap_b
        sign = -1.0

    own_sec = opp_sec = 0
    for v in sec:
        x = sign * v
        if x > 4.0:
            own_sec += 1
        elif x < -4.0:
            opp_sec += 1

    total = stones_b + stones_w
    mat = stones_o - stones_e + (6.5 if color == 'W' else -6.5)
    fmargin = fence_o - fence_e
    smargin = strong_o - strong_e
    tmargin = trap_o - trap_e
    lead = mat + 0.46 * fmargin + 0.22 * smargin + 0.72 * tmargin + 0.24 * (weak_e - weak_o)
    safe = weak_o <= weak_e + 4.8 and sev_o <= sev_e + 1
    strict = weak_o <= weak_e + 2.4 and sev_o <= sev_e

    return (
        total >= 32 and safe and mat >= -18.0
        and fmargin >= 9.0 and lead >= 9.0
        and own_sec >= opp_sec and trap_o + 2.0 >= trap_e
    ) or (
        total >= 35 and safe and mat >= -20.0
        and tmargin >= 5.0 and fmargin >= 3.0
        and lead >= 8.0 and own_sec + 1 >= opp_sec
    ) or (
        total >= 55 and strict and mat >= -16.0
        and smargin >= 7.5 and fmargin >= 6.5
        and lead >= 10.2 and own_sec >= opp_sec
    )

MOTIF_NAME = 'komi-adjusted settled stone ledger'
MOTIF_DESCRIPTION = 'The evaluated side has a komi-adjusted surplus of stable on-board stones and nearby influence without carrying a larger weak-group burden.'

def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    s = ''.join(board_rows)

    nb = [[] for _ in range(361)]
    for p in range(361):
        if p >= 19:
            nb[p].append(p - 19)
        if p < 342:
            nb[p].append(p + 19)
        if p % 19:
            nb[p].append(p - 1)
        if p % 19 != 18:
            nb[p].append(p + 1)

    gid = [-1] * 361
    gcol = []
    gstones = []
    glibs = []
    gcont = []
    libmark = [0] * 361
    mark = 0

    for i, ch in enumerate(s):
        if ch == '.' or gid[i] >= 0:
            continue
        g = len(gcol)
        q = [i]
        gid[i] = g
        h = 0
        libs = []
        cont = 0
        mark += 1
        while h < len(q):
            p = q[h]
            h += 1
            for y in nb[p]:
                v = s[y]
                if v == '.':
                    if libmark[y] != mark:
                        libmark[y] = mark
                        libs.append(y)
                elif v == ch:
                    if gid[y] < 0:
                        gid[y] = g
                        q.append(y)
                else:
                    cont += 1
        gcol.append(ch)
        gstones.append(q)
        glibs.append(libs)
        gcont.append(cont)

    n = len(gcol)
    geyes = [0] * n
    sf = [0.8] * n
    fn = [0.0] * n
    en = [0.0] * n
    seen = [0] * 361
    smark = 0

    for g, ch in enumerate(gcol):
        enemy = 'W' if ch == 'B' else 'B'
        eyes = 0
        for p in glibs[g]:
            bad = False
            for y in nb[p]:
                if s[y] == enemy:
                    bad = True
                    break
            if bad:
                continue
            r = p // 19
            c = p - r * 19
            diag = off = 0
            if r and c:
                diag += 1 if s[p - 20] == enemy else 0
            else:
                off += 1
            if r and c < 18:
                diag += 1 if s[p - 18] == enemy else 0
            else:
                off += 1
            if r < 18 and c:
                diag += 1 if s[p + 18] == enemy else 0
            else:
                off += 1
            if r < 18 and c < 18:
                diag += 1 if s[p + 20] == enemy else 0
            else:
                off += 1
            if diag <= (1 if off else 0):
                eyes += 1
        geyes[g] = eyes

        smark += 1
        for p in gstones[g]:
            r = p // 19
            c = p - r * 19
            for dr in (-2, -1, 0, 1, 2):
                rr = r + dr
                if rr < 0 or rr >= 19:
                    continue
                for dc in (-2, -1, 0, 1, 2):
                    md = abs(dr) + abs(dc)
                    if md == 0 or md > 2:
                        continue
                    cc = c + dc
                    if 0 <= cc < 19:
                        q = rr * 19 + cc
                        if seen[q] == smark or gid[q] == g:
                            continue
                        seen[q] = smark
                        v = s[q]
                        if v == ch:
                            fn[g] += 1.0 if md == 1 else 0.42
                        elif v == enemy:
                            en[g] += 1.0 if md == 1 else 0.42

    stones_o = stones_e = 0
    settled_o = settled_e = 0.0
    burden_o = burden_e = 0.0
    sev_o = sev_e = 0

    for g, ch in enumerate(gcol):
        sz = len(gstones[g])
        lc = len(glibs[g])
        eyes = geyes[g]
        press = en[g] - fn[g] + 0.05 * gcont[g]

        if eyes >= 2:
            f = 1.18
        elif eyes >= 1 and lc >= 6:
            f = 1.08
        elif lc >= 10 and press <= 3.0:
            f = 1.03
        elif lc >= 7 and press <= 1.5:
            f = 0.97
        elif lc >= 5:
            f = 0.84 if press <= 3.0 else 0.72
        elif lc == 4:
            f = 0.72 if eyes or press <= 0.5 else 0.55
        elif lc == 3:
            f = 0.62 if eyes else (0.45 if press <= 1.0 else 0.34)
        elif lc == 2:
            f = 0.46 if eyes else 0.22
        else:
            f = 0.12
        sf[g] = f

        weak = sz * max(0.0, 1.02 - f)
        if lc <= 1:
            weak += 4.0 + 0.35 * sz
            severe = 1
        elif lc == 2 and eyes == 0:
            weak += 1.5 + 0.20 * sz
            severe = 1
        elif lc <= 4 and eyes == 0 and press > 1.0:
            weak += 0.55 + 0.12 * sz + 0.20 * press
            severe = 0
        else:
            severe = 0

        val = sz * f + 0.10 * min(lc, 10) + 0.75 * eyes
        if ch == color:
            stones_o += sz
            settled_o += val
            burden_o += weak
            sev_o += severe
        else:
            stones_e += sz
            settled_e += val
            burden_e += weak
            sev_e += severe

    inf_o = inf_e = 0.0
    for p, ch in enumerate(s):
        if ch != '.':
            continue
        r = p // 19
        c = p - r * 19
        oi = ei = 0.0
        for dr in (-3, -2, -1, 0, 1, 2, 3):
            rr = r + dr
            if rr < 0 or rr >= 19:
                continue
            for dc in (-3, -2, -1, 0, 1, 2, 3):
                md = abs(dr) + abs(dc)
                if md == 0 or md > 3:
                    continue
                cc = c + dc
                if 0 <= cc < 19:
                    q = rr * 19 + cc
                    v = s[q]
                    if v == '.':
                        continue
                    w = (4 - md) * 0.17 * sf[gid[q]]
                    if v == color:
                        oi += w
                    else:
                        ei += w
        add = 0.36 if min(r, c, 18 - r, 18 - c) <= 3 else 0.25
        if oi > ei + 0.70 and oi > 0.95:
            inf_o += add
        elif ei > oi + 0.70 and ei > 0.95:
            inf_e += add

    komi = 6.5 if color == 'W' else -6.5
    stone_score = stones_o - stones_e + komi
    settled_score = settled_o - settled_e + komi
    infdiff = inf_o - inf_e
    est = 0.62 * stone_score + 0.42 * settled_score + 0.42 * (burden_e - burden_o) + 0.20 * infdiff
    phase = stones_o + stones_e >= 45
    safe = burden_o <= burden_e + 7.0 and sev_o <= sev_e + 1
    loose = burden_o <= burden_e + 10.0 and sev_o <= sev_e + 2

    return (
        phase and safe and est >= 6.1 and settled_score >= 1.0
        and stone_score >= -1.5 and inf_o + 4.0 >= inf_e
    ) or (
        phase and loose and est >= 8.6 and settled_score >= -0.5
        and stone_score >= -3.0 and sev_o <= sev_e + 1
    ) or (
        phase and loose and stone_score >= 5.0 and settled_score >= 4.2
        and inf_o + 6.0 >= inf_e
    )

MOTIF_NAME = 'edge-caged prisoner cushion'
MOTIF_DESCRIPTION = 'The evaluated side has a sizeable edge or corner net around opposing stones while keeping enough whole-board space and weak-group safety.'

def motif(board_rows: list[str], color: str) -> bool:
    if color not in ('B', 'W'):
        return False
    s = ''.join(board_rows)
    if len(s) != 361:
        return False

    gid = [-1] * 361
    gcol = []
    gsize = []
    glibs = []
    gcont = []
    gedge = []
    gcorner = []
    gspan = []
    libmark = [0] * 361
    mark = 0

    for i, ch in enumerate(s):
        if ch == '.' or gid[i] >= 0:
            continue
        g = len(gcol)
        q = [i]
        gid[i] = g
        h = 0
        libs = []
        cont = 0
        mn = 19
        crn = 40
        minr = minc = 19
        maxr = maxc = -1
        mark += 1
        while h < len(q):
            p = q[h]
            h += 1
            r = p // 19
            c = p - r * 19
            d = min(r, c, 18 - r, 18 - c)
            if d < mn:
                mn = d
            cd = min(r + c, r + 18 - c, 18 - r + c, 36 - r - c)
            if cd < crn:
                crn = cd
            if r < minr:
                minr = r
            if r > maxr:
                maxr = r
            if c < minc:
                minc = c
            if c > maxc:
                maxc = c
            for y in (p - 19 if p >= 19 else -1,
                      p + 19 if p < 342 else -1,
                      p - 1 if p % 19 else -1,
                      p + 1 if p % 19 != 18 else -1):
                if y < 0:
                    continue
                v = s[y]
                if v == '.':
                    if libmark[y] != mark:
                        libmark[y] = mark
                        libs.append(y)
                elif v == ch:
                    if gid[y] < 0:
                        gid[y] = g
                        q.append(y)
                else:
                    cont += 1
        gcol.append(ch)
        gsize.append(len(q))
        glibs.append(libs)
        gcont.append(cont)
        gedge.append(mn)
        gcorner.append(crn)
        gspan.append((maxr - minr + 1) * (maxc - minc + 1))

    eyes = [0] * len(gcol)
    sf = [0.0] * len(gcol)
    stones_b = stones_w = 0
    weak_b = weak_w = 0.0
    sev_b = sev_w = 0

    for g, ch in enumerate(gcol):
        enemy = 'W' if ch == 'B' else 'B'
        eys = 0
        for p in glibs[g]:
            if ((p >= 19 and s[p - 19] == enemy) or
                (p < 342 and s[p + 19] == enemy) or
                (p % 19 and s[p - 1] == enemy) or
                (p % 19 != 18 and s[p + 1] == enemy)):
                continue
            r = p // 19
            c = p - r * 19
            diag = off = 0
            if r and c:
                diag += 1 if s[p - 20] == enemy else 0
            else:
                off += 1
            if r and c < 18:
                diag += 1 if s[p - 18] == enemy else 0
            else:
                off += 1
            if r < 18 and c:
                diag += 1 if s[p + 18] == enemy else 0
            else:
                off += 1
            if r < 18 and c < 18:
                diag += 1 if s[p + 20] == enemy else 0
            else:
                off += 1
            if diag <= (1 if off else 0):
                eys += 1
        eyes[g] = eys

        sz = gsize[g]
        lc = len(glibs[g])
        cont = gcont[g]
        if eys >= 2:
            f = 1.26
        elif lc >= 9:
            f = 1.10
        elif eys and lc >= 5:
            f = 1.00
        elif lc >= 6:
            f = 0.88
        elif lc >= 4:
            f = 0.68
        elif lc == 3:
            f = 0.50 if eys else 0.32
        elif lc == 2:
            f = 0.36 if eys else 0.14
        else:
            f = 0.05
        sf[g] = f * (1.0 + 0.02 * min(sz, 12))

        weak = 0.0
        sev = 0
        if lc <= 1:
            weak = 4.2 + 1.0 * sz + 0.08 * cont
            sev = 1
        elif lc == 2:
            weak = 1.25 + 0.38 * sz + 0.06 * cont
            if eys:
                weak *= 0.42
            else:
                sev = 1
        elif lc == 3 and eys == 0:
            weak = 0.56 + 0.13 * sz + 0.05 * cont
        elif lc <= 5 and eys == 0 and cont >= lc + 2:
            weak = 0.20 + 0.06 * sz + 0.04 * cont

        if ch == 'B':
            stones_b += sz
            weak_b += weak
            sev_b += sev
        else:
            stones_w += sz
            weak_w += weak
            sev_w += sev

    def sup(p, col):
        r = p // 19
        c = p - r * 19
        t = 0.0
        for dr, dc, w in ((-1, 0, 1.25), (1, 0, 1.25), (0, -1, 1.25), (0, 1, 1.25),
                          (-1, -1, 0.55), (-1, 1, 0.55), (1, -1, 0.55), (1, 1, 0.55),
                          (-2, 0, 0.45), (2, 0, 0.45), (0, -2, 0.45), (0, 2, 0.45)):
            rr = r + dr
            cc = c + dc
            if 0 <= rr < 19 and 0 <= cc < 19:
                q = rr * 19 + cc
                if s[q] == col:
                    t += w * sf[gid[q]]
        return t

    cage_b = cage_w = 0.0
    best_b = best_w = 0.0
    corner_b = corner_w = 0.0
    net_b = net_w = 0.0
    cnt_b = cnt_w = 0

    for g, ch in enumerate(gcol):
        lc = len(glibs[g])
        sz = gsize[g]
        if lc > 8 or sz > 36 or eyes[g] >= 2 or gedge[g] > 4:
            continue
        if gspan[g] > 115 and lc > 4:
            continue
        cap = 'W' if ch == 'B' else 'B'
        ctl = esc = 0
        for p in glibs[g]:
            r = p // 19
            c = p - r * 19
            d = min(r, c, 18 - r, 18 - c)
            own = sup(p, ch)
            atk = sup(p, cap)
            emp = 0
            if p >= 19 and s[p - 19] == '.':
                emp += 1
            if p < 342 and s[p + 19] == '.':
                emp += 1
            if p % 19 and s[p - 1] == '.':
                emp += 1
            if p % 19 != 18 and s[p + 1] == '.':
                emp += 1
            if atk + (0.35 if d <= 1 else 0.0) > own + 0.50:
                ctl += 1
            elif emp >= 2 and d >= max(2, gedge[g] + 1) and own + 0.35 >= atk:
                esc += 1

        cont = gcont[g]
        eys = eyes[g]
        trapped = False
        if lc <= 1:
            trapped = True
        elif eys == 0 and lc <= 3 and (ctl >= 1 or cont >= 2):
            trapped = True
        elif eys == 0 and lc <= 6 and ctl * 2 >= lc and esc <= 1 and cont >= lc:
            trapped = True
        elif eys == 0 and lc <= 8 and gedge[g] <= 2 and ctl >= lc - 1 and esc == 0:
            trapped = True
        elif eys == 1 and lc <= 4 and ctl >= lc - 1 and esc == 0 and cont >= lc:
            trapped = True
        if not trapped:
            continue

        val = 1.0 + 0.52 * min(sz, 26) + 0.42 * max(0, 7 - lc)
        val += 0.42 * ctl + 0.18 * min(cont, 28)
        if gedge[g] <= 1:
            val += 1.25
        elif gedge[g] <= 3:
            val += 0.55
        if gcorner[g] <= 7:
            val += 1.35
        if eys:
            val *= 0.48
        if esc:
            val *= 0.78 if esc == 1 else 0.60
        if lc >= 7:
            val *= 0.82
        if val < 3.6:
            continue

        if cap == 'B':
            cage_b += val
            cnt_b += 1
            if val > best_b:
                best_b = val
            if lc >= 3:
                net_b += val
            if gcorner[g] <= 7:
                corner_b += val
        else:
            cage_w += val
            cnt_w += 1
            if val > best_w:
                best_w = val
            if lc >= 3:
                net_w += val
            if gcorner[g] <= 7:
                corner_w += val

    space_b = space_w = 0.0
    for p, ch in enumerate(s):
        if ch != '.':
            continue
        r = p // 19
        c = p - r * 19
        bi = wi = 0.0
        for dr in (-2, -1, 0, 1, 2):
            rr = r + dr
            if rr < 0 or rr >= 19:
                continue
            adr = -dr if dr < 0 else dr
            rem = 2 - adr
            for dc in range(-rem, rem + 1):
                if dr == 0 and dc == 0:
                    continue
                cc = c + dc
                if 0 <= cc < 19:
                    q = rr * 19 + cc
                    v = s[q]
                    if v == 'B':
                        bi += (3 - adr - (dc if dc >= 0 else -dc)) * sf[gid[q]]
                    elif v == 'W':
                        wi += (3 - adr - (dc if dc >= 0 else -dc)) * sf[gid[q]]
        val = 1.08 if min(r, c, 18 - r, 18 - c) <= 3 else 0.88
        if bi > wi * 1.28 + 0.70:
            space_b += val
        elif wi > bi * 1.28 + 0.70:
            space_w += val

    if color == 'B':
        stones_o, stones_e = stones_b, stones_w
        weak_o, weak_e = weak_b, weak_w
        sev_o, sev_e = sev_b, sev_w
        cage_o, cage_e = cage_b, cage_w
        best_o, best_e = best_b, best_w
        corner_o, corner_e = corner_b, corner_w
        net_o, net_e = net_b, net_w
        cnt_o, cnt_e = cnt_b, cnt_w
        space_o, space_e = space_b, space_w
    else:
        stones_o, stones_e = stones_w, stones_b
        weak_o, weak_e = weak_w, weak_b
        sev_o, sev_e = sev_w, sev_b
        cage_o, cage_e = cage_w, cage_b
        best_o, best_e = best_w, best_b
        corner_o, corner_e = corner_w, corner_b
        net_o, net_e = net_w, net_b
        cnt_o, cnt_e = cnt_w, cnt_b
        space_o, space_e = space_w, space_b

    total = stones_b + stones_w
    mat = stones_o - stones_e + (6.5 if color == 'W' else -6.5)
    cm = cage_o - cage_e
