            strip_count(minr - 4, minr, minc - 2, maxc + 3, enemy, friend),
            strip_count(maxr + 1, maxr + 5, minc - 2, maxc + 3, enemy, friend),
            strip_count(minr - 2, maxr + 3, minc - 4, minc, enemy, friend),
            strip_count(minr - 2, maxr + 3, maxc + 1, maxc + 5, enemy, friend),
        ):
            ewall += e
            fwall += f
            if e >= 2 and e > f:
