        if sz < 2 or lc < 3 or lc > 9 or eyes >= 2:
            continue
        if eyes == 1 and lc >= 8 and gcont[g] <= lc + 4 and gen[g] <= gfn[g] + 3.0:
            continue

        vals = []
        totc = 0
        for h, ct in adj[g].items():
            hlc = len(glibs[h])
            he = geyes[h]
            a = (hlc - lc) + 2.1 * (he - eyes) + 0.50 * min(ct, 4)
            if he >= 1 and eyes == 0:
                a += 0.8
            if glive[h]:
                a += 0.8
            if gweak[h] > 3.0:
                a -= 1.8
            if hlc <= 2 and he == 0:
                a -= 2.0
            if a > 0.4:
                vals.append(a)
            totc += ct

        if not vals:
            continue
        vals.sort(reverse=True)
        best = vals[0]
        second = vals[1] if len(vals) > 1 else 0.0
        surround = gen[g] - gfn[g] + 0.12 * gcont[g]
        if eyes == 0:
            surround += 0.7

        if best < 2.4 or surround < 0.8:
            continue
        if second < 0.8 and totc < 3 and lc > 5 and best < 4.8:
            continue

        v = 0.65 + 0.20 * min(sz, 16) + 0.34 * (9 - lc)
        v += 0.34 * best + 0.22 * second + 0.16 * min(surround, 10.0)
        if eyes == 0:
            v += 0.75
        else:
            v *= 0.76
        if lc <= 4:
            v += 0.55
        if sz >= 8:
            v += 0.05 * min(sz - 7, 12)
        if gedge[g] <= 1 and lc >= 6:
            v *= 0.70
        if gedge[g] == 0 and eyes and lc >= 5:
            v *= 0.65
        if gfn[g] > gen[g] + 2.0:
            v *= 0.55

        if v < 2.0:
            continue
        if ch == color:
            press_own += v
            cnt_own += 1
            if v > max_own:
                max_own = v
        else:
            press_opp += v
            cnt_opp += 1
            if v > max_opp:
                max_opp = v

    swing = press_opp - press_own + 0.08 * (weak_opp - weak_own)
    material_ok = stones_own - stones_opp + (6.5 if color == 'W' else -6.5) >= -22.0

    return (
        press_opp >= 4.2 and press_opp >= press_own + 2.4 and swing >= 2.4
        and weak_own <= weak_opp + 6.0 and sev_own <= sev_opp + 1 and material_ok
    ) or (
        max_opp >= 4.4 and max_opp >= max_own + 1.8 and press_opp >= press_own + 2.0
