        gweak[g] = weak

        if ch == color:
            stones_o += sz
            weak_o += weak
            sev_o += sev
        else:
            stones_e += sz
            weak_e += weak
            sev_e += sev

    def pt(edge, d, a):
        if edge == 0:
            return d * 19 + a
        if edge == 1:
            return (18 - d) * 19 + a
        if edge == 2:
            return a * 19 + d
        return a * 19 + (18 - d)

    def da(edge, p):
        r = p // 19
        c = p - r * 19
        if edge == 0:
            return r, c
        if edge == 1:
            return 18 - r, c
        if edge == 2:
            return c, r
        return 18 - c, r

    def edge_score(g, edge):
        ch = gcol[g]
        att = 'W' if ch == 'B' else 'B'
        sz = len(gstones[g])
        lc = glc[g]
        eyes = geyes[g]
        low2 = low3 = high = 0
        lo = 19
        hi = -1
        contact = 0.0

        for p in gstones[g]:
            d, a = da(edge, p)
            if d <= 2:
                low3 += 1
                if d <= 1:
                    low2 += 1
                if a < lo:
                    lo = a
                if a > hi:
                    hi = a
                for q in nb[p]:
                    if s[q] == att:
                        contact += 0.45
            elif d >= 4:
                high += 1

        if low2 < 2 or low3 < 3 or hi < lo:
            return 0.0
        span = hi - lo + 1
        if span < 3 and low3 < 4:
            return 0.0
        if low3 * 5 < sz * 3 or high > max(2, sz // 3):
            return 0.0
        if lc < 4 or gweak[g] > 7.5:
            return 0.0
        if not (eyes >= 1 or lc >= 7 or (lc >= 6 and span >= 5)):
            return 0.0

        wall = escape = gap = end = 0.0
        a0 = lo - 2
        if a0 < 0:
            a0 = 0
        a1 = hi + 2
        if a1 > 18:
            a1 = 18
        for a in range(a0, a1 + 1):
            for d, w in ((2, 0.70), (3, 1.00), (4, 0.55)):
                q = pt(edge, d, a)
                v = s[q]
                if v == att:
                    h = gid[q]
                    ww = w
                    if gweak[h] > 4.5 and geyes[h] == 0:
                        ww *= 0.45
                    elif geyes[h] or glc[h] >= 6:
                        ww *= 1.10
                    wall += ww
                elif v == ch:
                    escape += w
                elif v == '.' and d == 3 and lo <= a <= hi:
                    gap += 0.25

        for a in (lo - 1, hi + 1):
            if 0 <= a < 19:
                for d in (0, 1, 2):
                    if s[pt(edge, d, a)] == att:
                        end += 0.55

        if wall + end < 3.0:
            return 0.0
        if wall + 0.45 * end < escape + 1.1:
            return 0.0

        val = 0.48 * wall + 0.32 * end + 0.25 * min(contact, 8.0)
        val += 0.34 * span + 0.18 * low3 + 0.18 * min(lc, 12)
        val += 0.55 * min(eyes, 2) - 0.55 * escape - 0.20 * gap
        if eyes == 0 and lc < 8:
            val -= 0.35
        if lc <= 5 and eyes == 0:
            val *= 0.65
        if span >= 6 and wall >= 5.0:
            val += 0.9
        if low2 >= 5:
            val += 0.45
        return val if val >= 3.1 else 0.0

    profit_o = profit_e = 0.0
    best_o = best_e = 0.0
    cnt_o = cnt_e = 0

    for g, ch in enumerate(gcol):
        for edge in (0, 1, 2, 3):
            v = edge_score(g, edge)
            if not v:
                continue
            if ch == opp:
                profit_o += v
                cnt_o += 1
                if v > best_o:
                    best_o = v
            else:
                profit_e += v
                cnt_e += 1
                if v > best_e:
                    best_e = v

    low_o = low_e = mid_o = mid_e = 0
    for p, ch in enumerate(s):
        if ch == '.':
            continue
        r = p // 19
        c = p - r * 19
        d = min(r, c, 18 - r, 18 - c)
        if d <= 1:
            if ch == color:
                low_o += 1
            else:
                low_e += 1
        elif d <= 3:
            if ch == color:
                mid_o += 1
            else:
                mid_e += 1

    line_bias = (low_e - low_o) + 0.35 * (mid_o - mid_e)
    mat = stones_o - stones_e + (6.5 if color == 'W' else -6.5)
    adv = profit_o - profit_e + 0.08 * line_bias + 0.035 * (weak_e - weak_o)
    calm = weak_e - weak_o <= 12.0 and sev_e <= sev_o + 2

    return (
        profit_o >= 5.0 and adv >= 2.6 and cnt_o >= cnt_e + 1
        and best_o >= 3.8 and weak_o <= weak_e + 8.5
        and -30.0 <= mat <= 28.0 and calm
    ) or (
        best_o >= 5.5 and best_o >= best_e + 2.4
        and profit_o >= profit_e + 2.0 and line_bias >= -3.0
        and weak_o <= weak_e + 10.0 and -32.0 <= mat <= 32.0 and calm
    ) or (
        cnt_o >= 2 and profit_o >= 7.8 and adv >= 3.3
        and weak_o <= weak_e + 11.0 and sev_o <= sev_e + 2
        and mat >= -30.0 and calm
    )

