        if bd[0] and not bd[1]:
            terr[0] += size * (0.76 if size <= 38 else 0.42)
        elif bd[1] and not bd[0]:
            terr[1] += size * (0.76 if size <= 38 else 0.42)
        elif size <= 46 and bd[0] + bd[1] > 0:
            d=bd[0]-bd[1]; t=bd[0]+bd[1]
            if d*3 > t:
                terr[0] += size * 0.14*d/t
            elif -d*3 > t:
                terr[1] += size * 0.14*(-d)/t

