          (-2,-1,1),(-2,1,1),(2,-1,1),(2,1,1),
          (-1,-2,1),(1,-2,1),(-1,2,1),(1,2,1))
    for p,ch in enumerate(s):
        if ch != '.':
            continue
        r=p//19; c=p%19; ib=iw=0.0
        for dr,dc,ww in offs:
            rr=r+dr; cc=c+dc
            if 0 <= rr < 19 and 0 <= cc < 19:
                q=rr*19+cc; v=s[q]
                if v == 'B':
                    ib += ww*gwt[gid[q]]
                elif v == 'W':
