    for i in range(4):
        if stripe[me][i] > stripe[op][i] + 1.6 and stripe[me][4+i] > stripe[op][4+i] + 1.6:
            paired += 1

    mat=stones[me]-stones[op] + (6.5 if color == 'W' else -6.5)
    td=terr[me]-terr[op]
    inf=ctrl[me]-ctrl[op]
    plain=mat + 0.48*td + 0.10*(res[me]-res[op]) + 0.15*(weak[op]-weak[me])
    static=plain + 0.30*inf
    safe=weak[me] <= weak[op] + 3.5 and urg[me] <= urg[op] + 1 and res[me] >= res[op] - 5.0
    quiet=weak[op] <= weak[me] + 8.2 and urg[op] <= urg[me] + 2
    floor=mat >= -8.8 and td >= -14.5
    buried=plain <= 4.8 and mat <= 6.0 and (td <= 4.5 or mat <= 1.0)
    score=static + 0.045*lead

    return (
        total >= 34 and safe and quiet and floor and buried and 3.0 <= static <= 18.0
        and inf >= 7.0 and wins >= loss + 2 and wins >= 4
        and lead >= 16.0 and mainlead >= 3.0 and antilead >= 3.0
        and paired >= 1 and score >= 5.0
    ) or (
        total >= 46 and safe and floor and buried and 2.0 <= static <= 20.0
        and inf >= 12.0 and wins >= 5 and loss <= 2
        and lead >= 24.0 and min(mainlead, antilead) >= 5.0
        and paired >= 2 and score >= 5.2
    ) or (
