            if y < 0:
                off += 1
            else:
                v = s[y]
                if v == 'B':
                    adj[0] += 1; g = gid[y]
                    if g not in gr[0]: gr[0].append(g)
                elif v == 'W':
                    adj[1] += 1; g = gid[y]
                    if g not in gr[1]: gr[1].append(g)
        diag = [0, 0]
        for y in (p-20 if r and c else -1, p-18 if r and c < 18 else -1,
                  p+18 if r < 18 and c else -1, p+20 if r < 18 and c < 18 else -1):
            if y >= 0:
                v = s[y]
                if v == 'B': diag[0] += 1
                elif v == 'W': diag[1] += 1
        for k in (0, 1):
            o = 1 - k
            if adj[o]:
                continue
            empty_orth = 4 - off - adj[k]
            wall = adj[k] + off
            if wall >= 2 and (wall >= 3 or off or empty_orth <= 1) and gr[k]:
                bad = diag[o]
                lim = 1 if off == 0 else 0
                if bad <= lim:
                    for g in gr[k]:
                        RE[g] += 1
                elif wall + diag[k] >= 2:
                    fp[k] += 1
                    for g in gr[k]:
                        FE[g] += 1

    stones = [0, 0]; weak = [0.0, 0.0]; sev = [0, 0]; res = [0.0, 0.0]
    for g, ch in enumerate(C):
        k = 0 if ch == 'B' else 1
        z = Z[g]; lc = LC[g]; e = 2 if RE[g] > 2 else RE[g]
        stones[k] += z
