                for y in (p-20 if r and c else -1, p-18 if r and c < 18 else -1,
                          p+18 if r < 18 and c else -1, p+20 if r < 18 and c < 18 else -1):
                    if y >= 0:
                        if s[y] == oc: att += 1
                        elif s[y] == ch: sup += 1
            sur = att - 0.70*sup + 0.42*CT[g]
            if sur >= 1.0 or fe >= 2:
                val = 1.55*fe + 0.48*max(0, 11-lc) + 0.16*min(z, 18)
                val += 0.045*min(CT[g], 28) + 0.075*sur
                if re == 0: val += 1.05
                if lc >= 9: val *= 0.82
                if sur < 3.0 and fe == 1: val *= 0.78
                if val >= 3.2:
                    burden[k] += val; bcnt[k] += 1
                    if val > top[k]: top[k] = val

        if z >= 2 and 3 <= lc <= 7 and re <= 1:
            blocked = clamps = 0
            for p in L[g]:
                r = p // 19; c = p % 19
                aa = da = free = off = 0
                for y in (p-19 if p >= 19 else -1, p+19 if p < 342 else -1,
                          p-1 if c else -1, p+1 if c != 18 else -1):
                    if y < 0:
                        off += 1
                    else:
                        v = s[y]
                        if v == oc: aa += 1
                        elif v == '.': free += 1
                for y in (p-20 if r and c else -1, p-18 if r and c < 18 else -1,
                          p+18 if r < 18 and c else -1, p+20 if r < 18 and c < 18 else -1):
                    if y >= 0 and s[y] == oc:
