    safe = weak[me] <= weak[op] + 4.0 and sev[me] <= sev[op] + 1
    reserve = res[me] >= res[op] - 6.5
    fadv = fp[op] - fp[me]

    return (
        safe and reserve and mat >= -12.5 and -3.8 <= est <= 17.0
