            else: off += 1
            if r and c < 18: bad += s[p-18] == oc
            else: off += 1
            if r < 18 and c: bad += s[p+18] == oc
            else: off += 1
            if r < 18 and c < 18: bad += s[p+20] == oc
            else: off += 1
