                core[1] += 0.45 * v

    me = 0 if color == 'B' else 1
    op = 1 - me
    total = stones[0] + stones[1]
    if total < 36:
        return False

    qwin = qloss = 0; qlead = 0.0
    for i in range(4):
        d = quad[me][i] - quad[op][i]
        if d > 1.55:
            qwin += 1; qlead += min(d, 7.0)
        elif d < -1.55:
            qloss += 1

    mat = stones[me] - stones[op] + (6.5 if color == 'W' else -6.5)
    td = terr[me] - terr[op]
    plain = mat + 0.40*td + 0.08*(res[me]-res[op]) + 0.13*(weak[op]-weak[me])
    spacelead = space[me] - space[op]
    corelead = core[me] - core[op]
    stonelead = stonec[me] - stonec[op]
    gatelead = gate[me] - gate[op]
    halo = spacelead + 0.45*corelead + 0.22*stonelead + 0.35*gatelead + 0.08*qlead
    score = plain + 0.19*spacelead + 0.08*corelead + 0.10*gatelead

    safe = weak[me] <= weak[op] + 4.2 and urg[me] <= urg[op] + 2 and res[me] >= res[op] - 6.0
    floor = plain >= -7.0 and mat >= -9.5 and td >= -15.0
    hidden = plain <= 4.7 and (mat <= 9.5 or td <= 4.8)
    hollow = space[me] >= 7.5 and spacelead >= 4.0 and stonelead <= 16.0
    hollow = hollow and spacelead >= 0.25 * max(0.0, stonelead) + 3.5

    return (
        total >= 38 and safe and floor and hidden and hollow
        and spacelead >= 6.2 and corelead >= 1.2
        and qwin >= 2 and qwin >= qloss + 1
        and halo >= 8.4 and score >= 2.0
    ) or (
        total >= 52 and safe and floor and plain <= 5.6 and hollow
        and spacelead >= 9.4 and corelead >= 1.8
        and qwin >= 3 and qloss <= 1
        and halo >= 12.2 and score >= 2.2
    ) or (
        total >= 42 and safe and floor and hidden
        and gatelead >= 3.0 and spacelead >= 4.6 and corelead >= 2.4
        and stonelead <= 18.5 and qwin >= 2
        and halo >= 8.0 and score >= 2.3
    )
